import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

// Hand-written in-process double for the downstream pricing service.
const prices = { A: 10, B: 2.5, BIG: 60, CENT: 33.33 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw = false) =>
  fetch(`${base}/orders`, { method: 'POST', body: raw ? body : JSON.stringify(body) })
const json = async (res) => res.json()

test('POST /orders creates an order, sums price*qty, id is a string', async () => {
  calls.length = 0
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 4 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await json(res)
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 4 }], total: 30 })
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(calls, ['A', 'B'])
})

test('POST /orders ids are sequential strings', async () => {
  const a = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'A', qty: 10 }] }))).total, 100)
})

test('POST /orders total above 100 gets 10% off', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'BIG', qty: 2 }] }))).total, 108)
})

test('POST /orders total is floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor truncates cents; 33.33 -> 33
  assert.equal((await json(await post({ items: [{ sku: 'CENT', qty: 1 }] }))).total, 33)
  // 100.5 > 100 so discounted: 90.45 -> 90
  assert.equal((await json(await post({ items: [{ sku: 'A', qty: 10 }, { sku: 'B', qty: 0.2 }] }))).total, 90)
})

test('POST /orders with unknown sku yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — undefined price -> NaN -> serialised as null, still 201
  const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await json(res)).total, null)
})

test('POST /orders with missing qty yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await json(res)).total, null)
})

for (const [name, body, raw] of [
  ['empty items', { items: [] }],
  ['missing items', {}],
  ['items not an array', { items: 'A' }],
  ['empty body', '', true],
  ['invalid JSON', '{nope', true],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await json(res), { error: 'items required' })
  })
}

test('GET /orders/:id returns a created order', async () => {
  const created = await json(await post({ items: [{ sku: 'A', qty: 3 }] }))
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await json(res), created)
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await json(res), { error: 'not found' })
})

test('unknown routes and unsupported methods answer 404 no route', async () => {
  const cases = [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'], ['GET', '/other'],
    ['DELETE', '/orders/1'], ['PUT', '/orders/1'], ['POST', '/orders/1'],
  ]
  for (const [method, path] of cases) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await json(res), { error: 'no route' }, `${method} ${path}`)
  }
})

test('query string is ignored when routing', async () => {
  assert.equal((await fetch(`${base}/orders/x?y=1`)).status, 200)
})

test('pricing client reads price from GET /prices/:sku and url-encodes the sku', async () => {
  const seen = []
  const stub = createServer((req, res) => {
    seen.push(req.url)
    res.end(JSON.stringify({ price: 7 }))
  })
  await new Promise((r) => stub.listen(0, r))
  try {
    const client = createPricingClient(`http://localhost:${stub.address().port}`)
    assert.equal(await client.priceOf('a b/c'), 7)
    assert.deepEqual(seen, ['/prices/a%20b%2Fc'])
  } finally { stub.close() }
})
